/**
 * Applies every SQL file in src/server/db/migrations in name order.
 *
 * Plain JavaScript so the container's boot script can run it without tsx;
 * `scripts/migrate.ts` is a thin wrapper over the same function, so there is
 * one migrator and not two.
 *
 * Why not `drizzle-orm/libsql/migrator`, which the Railway readiness note
 * asked for: the drizzle journal at `migrations/meta/_journal.json` lists two
 * of the eight migration files, because every migration from CR02 onwards was
 * written by hand rather than generated by drizzle-kit. The drizzle migrator
 * walks the journal, so it would apply `0000_init` and `0001_cr01_trends_ask`
 * and silently skip the six files that create most of the product's tables.
 * It also keeps its own ledger, so against a database restored from a bundle,
 * which is already fully migrated, it would try to create every table again
 * and fail. This migrator records a content hash per file and tolerates the
 * re-run errors those hand-written files produce, which is what makes it safe
 * to run at every container start.
 */
import { createClient } from "@libsql/client";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const IGNORABLE =
  /already exists|duplicate column name|Cannot add a column to a view|no such column: .* in index/i;

export function migrationsDir(root = process.cwd()) {
  return path.join(root, "src", "server", "db", "migrations");
}

/**
 * @param {{ dbUrl: string, root?: string, quiet?: boolean }} opts
 * @returns {Promise<{ applied: string[], skipped: number }>}
 */
export async function applyMigrations(opts) {
  const log = opts.quiet ? () => undefined : console.log;
  const root = opts.root ?? process.cwd();
  const client = createClient({ url: opts.dbUrl });
  try {
    await client.execute("PRAGMA journal_mode = WAL;");
    await client.execute(
      "CREATE TABLE IF NOT EXISTS `_migrations` (`name` text PRIMARY KEY, `hash` text NOT NULL, `applied_at` text NOT NULL)"
    );
    const applied = new Map();
    for (const row of (await client.execute("SELECT name, hash FROM `_migrations`")).rows) {
      applied.set(String(row.name), String(row.hash));
    }

    const dir = migrationsDir(root);
    const files = fs
      .readdirSync(dir)
      .filter((f) => f.endsWith(".sql"))
      .sort();
    const ran = [];
    let skipped = 0;
    for (const f of files) {
      const sql = fs.readFileSync(path.join(dir, f), "utf8");
      const hash = crypto.createHash("sha1").update(sql).digest("hex");
      if (applied.get(f) === hash) {
        skipped++;
        continue;
      }
      const statements = sql
        .split(/-->\s*statement-breakpoint/g)
        .map((s) => s.trim())
        .filter(Boolean);
      for (const stmt of statements) {
        try {
          await client.execute(stmt);
        } catch (e) {
          const msg = String(e?.message || e);
          if (IGNORABLE.test(msg)) continue;
          // CR07: statements that cannot be written with IF NOT EXISTS (a table
          // rename, for one) carry this marker and may fail on a rerun.
          if (/--\s*idempotent:/i.test(stmt)) {
            log(`  (skipped idempotent statement: ${msg.slice(0, 80)})`);
            continue;
          }
          console.error(`Migration ${f} failed on:\n${stmt.slice(0, 200)}\n${msg}`);
          throw e;
        }
      }
      await client.execute({
        sql: "INSERT INTO `_migrations` (name, hash, applied_at) VALUES (?, ?, ?) ON CONFLICT(name) DO UPDATE SET hash = excluded.hash, applied_at = excluded.applied_at",
        args: [f, hash, new Date().toISOString()],
      });
      ran.push(f);
      log(`applied ${f}`);
    }
    if (!ran.length) log("migrations up to date");
    return { applied: ran, skipped };
  } finally {
    client.close();
  }
}
